#!/bin/bash
# Check the tables of the last blocks level by level, in pieces (CycleCert.lean; the pieces are generated by
# cycle_gen.py into CycleData/, CyclePieces/, CycleLevels/ and CycleRun.lean), in parallel, after check.sh.  Kernel
# only (`decide +kernel`).
#
# usage: check_cycles.sh K [PASSES] [JOBS]      LEAN, LEANLIB as for check.sh
#   K        tables for the last 1 … K blocks (CycleRun.lean: lvl1 … lvlK, cycle1 … cycleK)
#   PASSES   passes of the last table after them, for the bound (default 0)
# With RESUME=1 it keeps the generated files and skips those already checked (after an interrupted run).
#
# 16 levels take about a minute; 30 levels and 4 passes (6,000 pieces) about 6 CPU hours.
set -e
cd "$(dirname "$0")"
K=${1:?usage: check_cycles.sh K [PASSES] [JOBS]}
PASSES=${2:-0}
JOBS=${3:-$(nproc)}
LEAN=${LEAN:-lean}
if [ -z "$LEANLIB" ]; then LEANLIB="$(dirname "$(command -v "$LEAN")")/../lib/lean"; fi
TOOLS="$(cd ../../tools/lean && pwd)"
export LEAN LEAN_PATH="$LEANLIB:$TOOLS/out:$(pwd)/out" RESUME
[ -f out/Periods.olean ] || { echo "run check.sh first"; exit 1; }

if [ "$RESUME" != 1 ]; then
  python3 cycle_gen.py "$K" "$PASSES"
  rm -rf out/CycleData out/CyclePieces out/CycleLevels
fi
mkdir -p out/CycleData out/CyclePieces out/CycleLevels

check() {  # check FILE: compile one file to its .olean
  o="out/${1%.lean}.olean"
  if [ "$RESUME" = 1 ] && [ "$o" -nt "$1" ]; then return; fi
  s=$SECONDS
  $LEAN "$1" -o "$o"
  echo "== $1 ($((SECONDS - s)) s)"
}
export -f check

check TableLit.lean
check CycleCert.lean
ls CycleData/D*_*.lean | xargs -P "$JOBS" -I{} bash -c 'check {}'
ls CycleData/D*.lean | grep -v _ | xargs -P "$JOBS" -I{} bash -c 'check {}'
ls CyclePieces/*.lean | xargs -P "$JOBS" -I{} bash -c 'check {}'
ls CycleLevels/*.lean | xargs -P "$JOBS" -I{} bash -c 'check {}'
check CycleRun.lean
echo "ALL CHECKED (cycles, kernel)"
